'use strict';
(()=>{const params=new URL(location.href).searchParams,result=params.get('result')||'pending',title=document.querySelector('[data-return-title]'),message=document.querySelector('[data-return-message]'),mark=document.querySelector('[data-return-mark]'),help=document.querySelector('[data-return-help]'),progress=document.querySelector('[data-return-progress]');const finish=(heading,text,symbol,confirmed=false)=>{title.textContent=heading;message.textContent=text;mark.textContent=symbol;mark.classList.toggle('confirmed',confirmed);progress.classList.add('complete');progress.setAttribute('aria-valuenow','100')};if(result==='success')setTimeout(()=>finish('Pagamento aprovado','A confirmação foi recebida. O pedido será atualizado automaticamente no NeoPeptídeos.','✓',true),1800);else if(result==='failure')setTimeout(()=>{finish('Pagamento não concluído','Nenhuma confirmação foi recebida. Abra o NeoPeptídeos para tentar novamente ou escolher outra forma de pagamento.','!');help.textContent='Feche esta tela do navegador e abra novamente o NeoPeptídeos pelo ícone instalado.'},900);else setTimeout(()=>{title.textContent='Pagamento em análise';message.textContent='O Mercado Pago ainda está processando. O pedido será atualizado automaticamente quando houver confirmação.';mark.textContent='…';help.textContent='Você já pode fechar esta tela do navegador e abrir novamente o NeoPeptídeos pelo ícone instalado.'},1400)})();
